// apü client runtime for Go (standard library only; Go ≥ 1.24). Embedded into every file
// generated by `apue-types --lang go`; the generated part at the end adds the API's types and one
// method per operation.
//
// HTTP/2 over TLS (net/http; HTTP/1.1 if the server or a proxy can't do h2). A Client is safe for
// concurrent use; its calls share one connection. Covers: unary calls (GET ?i= with canonical
// JSON for cacheable reads, POST otherwise, Idempotency-Key for non-safe calls, retries for safe
// and keyed calls), server streams, client and bidi streams (full duplex over HTTP/2), RFC 9457
// problems as *Error (also in END frames), deadlines (apue-timeout) and context cancellation,
// bytes in messages (BLOB frames), uploads for bytes and file inputs, and t.download() outputs
// (resumed with Range + If-Range, SHA-256 verified).
//
// Not covered: resuming broken streams (resume tokens), batches, QUERY, field selection,
// compression, client-side validation (the server validates).
package apue

import (
	"bytes"
	"context"
	"crypto/rand"
	"crypto/sha256"
	"crypto/tls"
	"crypto/x509"
	"encoding/base64"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"iter"
	"math"
	mrand "math/rand/v2"
	"net"
	"net/http"
	"net/url"
	"os"
	"reflect"
	"slices"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"
	"unicode/utf16"
)

const (
	mediaStream  = "application/vnd.apue.frames"
	mediaJSON    = "application/json"
	mediaProblem = "application/problem+json"
	acceptValue  = "application/vnd.apue.frames, application/json;q=0.9, application/problem+json;q=0.8"
	maxGetURL    = 2048
	blobChunk    = 64 * 1024
	maxFrame     = 16 << 20 // larger frames are refused before they are buffered
	maxMessage   = 64 << 20 // per message: a JSON body, or the blobs of one MSG
	uploadsPath  = "/$uploads"

	frameMsg   = 0x00
	frameEnd   = 0x01
	frameBlob  = 0x02
	flagLast   = 0x02
	headerSize = 8

	filePlaceholder = "$apue.file" // marks a File in an input until it is uploaded
)

// ---- errors ------------------------------------------------------------------------------------

// Error is an RFC 9457 problem: the call failed with Status (HTTP status code semantics), either
// as the HTTP response or in a stream's END frame.
type Error struct {
	Status    int
	Type      string // problem type URI; "about:blank" for generic errors
	Title     string
	Detail    string
	Retryable bool
	// Problem is the problem object as received, extension members (such as "fields") included.
	Problem map[string]any
}

func (e *Error) Error() string {
	if e.Detail != "" {
		return fmt.Sprintf("apue: %d %s: %s", e.Status, e.Title, e.Detail)
	}
	return fmt.Sprintf("apue: %d %s", e.Status, e.Title)
}

func newError(status int, problem map[string]any) *Error {
	if problem == nil {
		problem = map[string]any{}
	}
	e := &Error{Status: status, Type: "about:blank", Title: http.StatusText(status), Problem: problem}
	if s, ok := problem["type"].(string); ok {
		e.Type = s
	}
	if s, ok := problem["title"].(string); ok {
		e.Title = s
	}
	if e.Title == "" {
		e.Title = "Error"
	}
	if s, ok := problem["detail"].(string); ok {
		e.Detail = s
	}
	if b, ok := problem["retryable"].(bool); ok {
		e.Retryable = b
	}
	return e
}

// badGateway reports a response the client can't use (truncated or malformed streams, a download
// that changed): 502, like the other apü clients.
func badGateway(title, detail string) *Error {
	return newError(http.StatusBadGateway, map[string]any{"title": title, "status": http.StatusBadGateway, "detail": detail})
}

func problemFrom(status int, body []byte) *Error {
	var problem map[string]any
	if json.Unmarshal(body, &problem) != nil {
		problem = nil
	}
	return newError(status, problem)
}

// ---- client ------------------------------------------------------------------------------------

// Client calls an apü API. Create it with NewClient; it is safe for concurrent use.
type Client struct {
	baseURL    string
	base       *url.URL
	http       *http.Client
	auth       string
	retries    int
	backoff    time.Duration
	maxBackoff time.Duration
}

// Option configures a Client.
type Option func(*clientConfig) error

type clientConfig struct {
	tls        *tls.Config
	roots      *x509.CertPool
	httpClient *http.Client
	auth       string
	retries    int
	backoff    time.Duration
}

// WithCA trusts the PEM certificates in addition to the system's.
func WithCA(pem []byte) Option {
	return func(c *clientConfig) error {
		if c.roots == nil {
			pool, err := x509.SystemCertPool()
			if err != nil {
				pool = x509.NewCertPool()
			}
			c.roots = pool
		}
		if !c.roots.AppendCertsFromPEM(pem) {
			return errors.New("apue: no certificate found in the CA PEM")
		}
		return nil
	}
}

// WithCAFile trusts the PEM certificates in the file in addition to the system's.
func WithCAFile(path string) Option {
	return func(c *clientConfig) error {
		pem, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		return WithCA(pem)(c)
	}
}

// WithTLSConfig sets the TLS configuration of the default transport.
func WithTLSConfig(config *tls.Config) Option {
	return func(c *clientConfig) error { c.tls = config; return nil }
}

// WithHTTPClient replaces the default HTTP client (see NewTransport); TLS options are then ignored.
func WithHTTPClient(client *http.Client) Option {
	return func(c *clientConfig) error { c.httpClient = client; return nil }
}

// WithAuthorization sends this Authorization header value with every request.
func WithAuthorization(value string) Option {
	return func(c *clientConfig) error { c.auth = value; return nil }
}

// WithRetries sets how often safe and keyed calls are retried (default 2).
func WithRetries(n int) Option {
	return func(c *clientConfig) error { c.retries = max(0, n); return nil }
}

// WithBackoff sets the base delay of the retries' exponential backoff with full jitter (default 100 ms).
func WithBackoff(d time.Duration) Option {
	return func(c *clientConfig) error { c.backoff = d; return nil }
}

// NewTransport is the HTTP transport a Client uses by default: HTTP/2 (full duplex request streams),
// no transparent compression (Range requests must see the identity encoding), HTTP/2 pings so a
// dead connection is noticed during long streams.
func NewTransport(config *tls.Config) *http.Transport {
	return &http.Transport{
		Proxy:                 http.ProxyFromEnvironment,
		DialContext:           (&net.Dialer{Timeout: 30 * time.Second, KeepAlive: 30 * time.Second}).DialContext,
		TLSClientConfig:       config,
		ForceAttemptHTTP2:     true,
		DisableCompression:    true,
		MaxIdleConns:          100,
		IdleConnTimeout:       90 * time.Second,
		TLSHandshakeTimeout:   10 * time.Second,
		ExpectContinueTimeout: time.Second,
		HTTP2:                 &http.HTTP2Config{SendPingTimeout: 30 * time.Second, PingTimeout: 15 * time.Second},
	}
}

// NewClient returns a client for the API at baseURL (https only).
func NewClient(baseURL string, opts ...Option) (*Client, error) {
	base, err := url.Parse(strings.TrimRight(baseURL, "/"))
	if err != nil {
		return nil, err
	}
	if base.Scheme != "https" {
		return nil, errors.New("apue: apü servers speak HTTPS (the base URL must start with https://)")
	}
	config := clientConfig{retries: 2, backoff: 100 * time.Millisecond}
	for _, opt := range opts {
		if err := opt(&config); err != nil {
			return nil, err
		}
	}
	hc := config.httpClient
	if hc == nil {
		tc := &tls.Config{}
		if config.tls != nil {
			tc = config.tls.Clone()
		}
		if config.roots != nil {
			tc.RootCAs = config.roots
		}
		hc = &http.Client{Transport: NewTransport(tc)}
	}
	return &Client{baseURL: base.String(), base: base, http: hc, auth: config.auth, retries: config.retries, backoff: config.backoff, maxBackoff: 2 * time.Second}, nil
}

// Close releases idle connections.
func (c *Client) Close() error {
	c.http.CloseIdleConnections()
	return nil
}

// CallOption configures one call.
type CallOption func(*callConfig)

type callConfig struct {
	timeout time.Duration
	key     string
}

// WithTimeout sets the call's deadline on the server (apue-timeout); past it the server answers
// 504. Without it, the context's deadline (if any) is sent.
func WithTimeout(d time.Duration) CallOption {
	return func(c *callConfig) { c.timeout = d }
}

// WithIdempotencyKey sets the Idempotency-Key of a non-safe unary call (default: a random UUID per
// call, reused by its retries). The same key with the same input replays the stored result.
func WithIdempotencyKey(key string) CallOption {
	return func(c *callConfig) { c.key = key }
}

// Ptr returns a pointer to v (for optional fields).
func Ptr[T any](v T) *T { return &v }

func callOptions(opts []CallOption) callConfig {
	var config callConfig
	for _, opt := range opts {
		opt(&config)
	}
	return config
}

func (c *Client) headers(ctx context.Context, config callConfig) http.Header {
	h := http.Header{}
	h.Set("Accept", acceptValue)
	ms := int64(0)
	if config.timeout > 0 {
		ms = max(1, int64(math.Ceil(float64(config.timeout)/float64(time.Millisecond))))
	} else if deadline, ok := ctx.Deadline(); ok {
		ms = max(1, time.Until(deadline).Milliseconds())
	}
	if ms > 0 {
		h.Set("Apue-Timeout", strconv.FormatInt(ms, 10))
	}
	return h
}

func (c *Client) newRequest(ctx context.Context, method, target string, h http.Header, body io.Reader) (*http.Request, error) {
	req, err := http.NewRequestWithContext(ctx, method, target, body)
	if err != nil {
		return nil, err
	}
	for k, v := range h {
		req.Header[k] = v
	}
	if c.auth != "" {
		req.Header.Set("Authorization", c.auth)
	}
	return req, nil
}

func (c *Client) sleep(ctx context.Context, d time.Duration) error {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-t.C:
		return nil
	case <-ctx.Done():
		return context.Cause(ctx)
	}
}

func (c *Client) backoffFor(attempt int) time.Duration {
	limit := min(c.maxBackoff, c.backoff*time.Duration(1<<min(attempt, 20)))
	return time.Duration(mrand.Float64() * float64(limit))
}

// send sends a request with a replayable body; if retry, transport failures, 429/503 (honouring
// Retry-After) and 409 problems with "retryable": true are retried within the budget.
func (c *Client) send(ctx context.Context, method, path string, h http.Header, body []byte, retry bool) (*http.Response, error) {
	for attempt := 0; ; attempt++ {
		var reader io.Reader
		if body != nil {
			reader = bytes.NewReader(body)
		}
		req, err := c.newRequest(ctx, method, c.baseURL+path, h, reader)
		if err != nil {
			return nil, err
		}
		resp, err := c.http.Do(req)
		if err != nil {
			if ctx.Err() != nil || !retry || attempt >= c.retries {
				return nil, err
			}
			if err := c.sleep(ctx, c.backoffFor(attempt+1)); err != nil {
				return nil, err
			}
			continue
		}
		if retry && attempt < c.retries {
			if delay, ok := c.retryDelay(resp, attempt+1); ok {
				resp.Body.Close()
				if err := c.sleep(ctx, delay); err != nil {
					return nil, err
				}
				continue
			}
		}
		return resp, nil
	}
}

func (c *Client) retryDelay(resp *http.Response, attempt int) (time.Duration, bool) {
	switch resp.StatusCode {
	case http.StatusTooManyRequests, http.StatusServiceUnavailable:
		io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
		if d, ok := retryAfter(resp.Header.Get("Retry-After")); ok {
			return min(d, c.maxBackoff), true
		}
		return c.backoffFor(attempt), true
	case http.StatusConflict:
		if mediaType(resp.Header.Get("Content-Type")) != mediaProblem {
			return 0, false
		}
		// Only retryable when the server says so (an Idempotency-Key still in progress).
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		resp.Body.Close()
		resp.Body = io.NopCloser(bytes.NewReader(body))
		if problemFrom(resp.StatusCode, body).Retryable {
			return c.backoffFor(attempt), true
		}
	}
	return 0, false
}

// retryAfter parses Retry-After (RFC 9110 §10.2.3): delay-seconds or an HTTP-date.
func retryAfter(value string) (time.Duration, bool) {
	value = strings.TrimSpace(value)
	if value == "" {
		return 0, false
	}
	if n, err := strconv.ParseUint(value, 10, 32); err == nil {
		return time.Duration(n) * time.Second, true
	}
	if t, err := http.ParseTime(value); err == nil {
		return max(0, time.Until(t)), true
	}
	return 0, false
}

func mediaType(value string) string {
	base, _, _ := strings.Cut(value, ";")
	return strings.ToLower(strings.TrimSpace(base))
}

// ---- operations (registered by the generated code) --------------------------------------------

type opMeta struct {
	Effect       string         `json:"effect"`
	Stream       string         `json:"stream"`
	Input        map[string]any `json:"input"`
	Output       map[string]any `json:"output"`
	inBlobs      bool           // bytes in the input (request streams: BLOB frames)
	inUploads    bool           // bytes or files in the input (unary calls: uploads)
	outBlobs     bool           // bytes in the output (BLOB frames)
	outDownloads bool           // t.download() in the output
}

var ops = map[string]*opMeta{}

func registerOps(manifest string) {
	var parsed map[string]*opMeta
	if err := json.Unmarshal([]byte(manifest), &parsed); err != nil {
		panic("apue: invalid embedded manifest: " + err.Error())
	}
	for name, op := range parsed {
		op.inBlobs = hasTransfer(op.Input, "blob-frames")
		op.inUploads = op.inBlobs || hasTransfer(op.Input, "upload")
		op.outBlobs = hasTransfer(op.Output, "blob-frames")
		op.outDownloads = hasTransfer(op.Output, "download")
		ops[name] = op
	}
}

func lookup(name string) *opMeta {
	op, ok := ops[name]
	if !ok {
		panic("apue: unknown operation " + name)
	}
	return op
}

// hasTransfer reports whether a JSON Schema has `x-apue-transfer: kind` anywhere.
func hasTransfer(schema any, kind string) bool {
	switch s := schema.(type) {
	case map[string]any:
		if s["x-apue-transfer"] == kind {
			return true
		}
		for _, v := range s {
			if hasTransfer(v, kind) {
				return true
			}
		}
	case []any:
		for _, v := range s {
			if hasTransfer(v, kind) {
				return true
			}
		}
	}
	return false
}

func sub(schema map[string]any, key string) map[string]any {
	s, _ := schema[key].(map[string]any)
	return s
}

func transfer(schema map[string]any) string {
	s, _ := schema["x-apue-transfer"].(string)
	return s
}

// nonNull returns the non-null branch of a nullable schema ({"anyOf": [T, {"type": "null"}]}).
func nonNull(schema map[string]any) (map[string]any, bool) {
	branches, ok := schema["anyOf"].([]any)
	if !ok {
		return nil, false
	}
	for _, b := range branches {
		if m, ok := b.(map[string]any); ok && m["type"] != "null" {
			return m, true
		}
	}
	return map[string]any{}, true
}

// ---- JSON --------------------------------------------------------------------------------------

// decodeTree decodes JSON into maps, slices and json.Number (no precision lost).
func decodeTree(data []byte) (any, error) {
	d := json.NewDecoder(bytes.NewReader(data))
	d.UseNumber()
	var v any
	if err := d.Decode(&v); err != nil {
		return nil, err
	}
	return v, nil
}

// canonicalJSON is RFC 8785 (JCS) for a decoded tree: keys sorted by UTF-16 code units, numbers
// and strings serialised like ECMAScript — the GET URL is the same as other apü clients' (cache key).
func canonicalJSON(v any) (string, error) {
	var b strings.Builder
	err := writeCanonical(&b, v)
	return b.String(), err
}

func writeCanonical(b *strings.Builder, v any) error {
	switch x := v.(type) {
	case nil:
		b.WriteString("null")
	case bool:
		b.WriteString(strconv.FormatBool(x))
	case json.Number:
		n, err := esNumber(x)
		if err != nil {
			return err
		}
		b.WriteString(n)
	case string:
		writeJSString(b, x)
	case []any:
		b.WriteByte('[')
		for i, e := range x {
			if i > 0 {
				b.WriteByte(',')
			}
			if err := writeCanonical(b, e); err != nil {
				return err
			}
		}
		b.WriteByte(']')
	case map[string]any:
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Slice(keys, func(i, j int) bool {
			return slices.Compare(utf16.Encode([]rune(keys[i])), utf16.Encode([]rune(keys[j]))) < 0
		})
		b.WriteByte('{')
		for i, k := range keys {
			if i > 0 {
				b.WriteByte(',')
			}
			writeJSString(b, k)
			b.WriteByte(':')
			if err := writeCanonical(b, x[k]); err != nil {
				return err
			}
		}
		b.WriteByte('}')
	default:
		return fmt.Errorf("apue: cannot encode %T as JSON", v)
	}
	return nil
}

// esNumber formats a number like ECMAScript's Number#toString (what JSON.stringify writes).
func esNumber(n json.Number) (string, error) {
	f, err := strconv.ParseFloat(string(n), 64)
	if err != nil || math.IsInf(f, 0) || math.IsNaN(f) {
		return "", fmt.Errorf("apue: number %s is not representable", n)
	}
	if f == 0 {
		return "0", nil
	}
	format := byte('f')
	if abs := math.Abs(f); abs < 1e-6 || abs >= 1e21 {
		format = 'e'
	}
	s := strconv.FormatFloat(f, format, -1, 64)
	if format == 'e' {
		// 1e-07 → 1e-7, as ECMAScript writes it.
		if i := strings.Index(s, "e-0"); i >= 0 {
			s = s[:i+2] + s[i+3:]
		} else if i := strings.Index(s, "e+0"); i >= 0 {
			s = s[:i+2] + s[i+3:]
		}
	}
	return s, nil
}

func writeJSString(b *strings.Builder, s string) {
	b.WriteByte('"')
	for _, r := range s { // invalid UTF-8 becomes U+FFFD
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if r < 0x20 {
				fmt.Fprintf(b, `\u%04x`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
}

// encodeURIComponent percent-encodes like ECMAScript's function of that name.
func encodeURIComponent(s string) string {
	const digits = "0123456789ABCDEF"
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if 'A' <= c && c <= 'Z' || 'a' <= c && c <= 'z' || '0' <= c && c <= '9' || strings.IndexByte("-_.!~*'()", c) >= 0 {
			b.WriteByte(c)
		} else {
			b.WriteByte('%')
			b.WriteByte(digits[c>>4])
			b.WriteByte(digits[c&15])
		}
	}
	return b.String()
}

// sfString is an RFC 9651 sf-string.
func sfString(value string) (string, error) {
	for i := 0; i < len(value); i++ {
		if value[i] < 0x20 || value[i] > 0x7e {
			return "", errors.New("apue: an Idempotency-Key must be printable ASCII")
		}
	}
	return `"` + strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(value) + `"`, nil
}

func uuid4() string {
	var b [16]byte
	rand.Read(b[:])
	b[6] = b[6]&0x0f | 0x40
	b[8] = b[8]&0x3f | 0x80
	h := hex.EncodeToString(b[:])
	return h[:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:]
}

// ---- bytes in messages (BLOB frames, SPEC §6) --------------------------------------------------

func appendFrame(out []byte, kind, flags byte, payload []byte) []byte {
	var header [headerSize]byte
	header[0], header[1] = kind, flags
	binary.BigEndian.PutUint32(header[4:], uint32(len(payload)))
	return append(append(out, header[:]...), payload...)
}

// lookalike reports whether v would be taken for a blob reference or an escape ({"$blob"} or
// {"$lit"} as the only member).
func lookalike(v any) bool {
	m, ok := v.(map[string]any)
	if !ok || len(m) != 1 {
		return false
	}
	_, blob := m["$blob"]
	_, lit := m["$lit"]
	return blob || lit
}

// extract replaces the bytes (base64 strings in the marshalled tree, found through the schema)
// with {"$blob": k} references and escapes look-alikes anywhere as {"$lit": value}.
func extract(schema map[string]any, v any, blobs *[][]byte) (any, error) {
	if lookalike(v) {
		return map[string]any{"$lit": v}, nil
	}
	if branch, ok := nonNull(schema); ok {
		if v == nil {
			return nil, nil
		}
		return extract(branch, v, blobs)
	}
	if transfer(schema) == "blob-frames" {
		data, err := blobBytes(v)
		if err != nil {
			return nil, err
		}
		*blobs = append(*blobs, data)
		return map[string]any{"$blob": len(*blobs) - 1}, nil
	}
	var err error
	switch x := v.(type) {
	case []any:
		items := sub(schema, "items")
		for i := range x {
			if x[i], err = extract(items, x[i], blobs); err != nil {
				return nil, err
			}
		}
	case map[string]any:
		props := sub(schema, "properties")
		for k, e := range x {
			if x[k], err = extract(sub(props, k), e, blobs); err != nil {
				return nil, err
			}
		}
	}
	return v, nil
}

// blobBytes returns the bytes of a []byte field as marshalled (base64; nil marshals as null).
func blobBytes(v any) ([]byte, error) {
	switch x := v.(type) {
	case nil:
		return []byte{}, nil
	case string:
		return base64.StdEncoding.DecodeString(x)
	}
	return nil, fmt.Errorf("apue: expected bytes, got %T", v)
}

// restore resolves {"$blob": k} references and unescapes {"$lit": value} (SPEC §6).
func restore(v any, blobs [][]byte, used []bool) (any, error) {
	var err error
	switch x := v.(type) {
	case []any:
		for i := range x {
			if x[i], err = restore(x[i], blobs, used); err != nil {
				return nil, err
			}
		}
	case map[string]any:
		if len(x) == 1 {
			if lit, ok := x["$lit"]; ok {
				return lit, nil
			}
			if ref, ok := x["$blob"]; ok {
				n, _ := ref.(json.Number)
				i, err := strconv.Atoi(string(n))
				if err != nil || i < 0 || i >= len(blobs) || used[i] {
					return nil, badGateway("Malformed Stream", fmt.Sprintf("invalid blob reference %v", ref))
				}
				used[i] = true
				return blobs[i], nil
			}
		}
		for k, e := range x {
			if x[k], err = restore(e, blobs, used); err != nil {
				return nil, err
			}
		}
	}
	return v, nil
}

// encodeMessage is the frames of one request-stream message: BLOB frames for its bytes, then MSG.
func encodeMessage(op *opMeta, v any) ([]byte, error) {
	data, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	if !op.inBlobs {
		return appendFrame(nil, frameMsg, 0, data), nil
	}
	tree, err := decodeTree(data)
	if err != nil {
		return nil, err
	}
	var blobs [][]byte
	if tree, err = extract(op.Input, tree, &blobs); err != nil {
		return nil, err
	}
	if data, err = json.Marshal(tree); err != nil {
		return nil, err
	}
	var out []byte
	for _, blob := range blobs {
		if len(blob) == 0 {
			out = appendFrame(out, frameBlob, flagLast, nil)
		}
		for offset := 0; offset < len(blob); offset += blobChunk {
			end := min(offset+blobChunk, len(blob))
			flags := byte(0)
			if end == len(blob) {
				flags = flagLast
			}
			out = appendFrame(out, frameBlob, flags, blob[offset:end])
		}
	}
	return appendFrame(out, frameMsg, 0, data), nil
}

// decodeValue turns one received message into the generated Go type.
func decodeValue[T any](c *Client, op *opMeta, payload []byte, blobs [][]byte) (T, error) {
	var v T
	if len(payload) == 0 {
		payload = []byte("null")
	}
	if op.outBlobs {
		tree, err := decodeTree(payload)
		if err != nil {
			return v, badGateway("Malformed Stream", err.Error())
		}
		used := make([]bool, len(blobs))
		if tree, err = restore(tree, blobs, used); err != nil {
			return v, err
		}
		if n := countTrue(used); n != len(blobs) {
			return v, badGateway("Malformed Stream", fmt.Sprintf("message references %d of %d blobs", n, len(blobs)))
		}
		if payload, err = json.Marshal(tree); err != nil { // bytes → base64 → []byte fields
			return v, err
		}
	} else if len(blobs) > 0 {
		return v, badGateway("Malformed Stream", "blobs in a message without bytes")
	}
	if err := json.Unmarshal(payload, &v); err != nil {
		return v, badGateway("Bad Gateway", "the output does not match the generated types: "+err.Error())
	}
	if op.outDownloads {
		c.attach(reflect.ValueOf(&v), 0)
	}
	return v, nil
}

func countTrue(flags []bool) int {
	n := 0
	for _, f := range flags {
		if f {
			n++
		}
	}
	return n
}

// ---- responses ---------------------------------------------------------------------------------

// messages reads a response's values: one for a JSON body, each MSG of a framed body.
type messages struct {
	body   io.ReadCloser
	framed bool
	single []byte
	read   bool
	ended  bool
	header [headerSize]byte
}

func newMessages(resp *http.Response) (*messages, error) {
	ctype := mediaType(resp.Header.Get("Content-Type"))
	if resp.StatusCode >= 400 || ctype == mediaProblem {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		resp.Body.Close()
		return nil, problemFrom(resp.StatusCode, body)
	}
	if ctype == mediaStream {
		return &messages{body: resp.Body, framed: true}, nil
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxMessage+1))
	if err != nil {
		return nil, err
	}
	if len(body) > maxMessage {
		return nil, badGateway("Bad Gateway", "response larger than 64 MiB")
	}
	return &messages{body: resp.Body, single: body}, nil
}

// next returns the next message and its blobs; io.EOF after a successful END frame, *Error for an
// END frame with an error, a truncated or malformed stream.
func (m *messages) next() ([]byte, [][]byte, error) {
	if !m.framed {
		if m.read {
			return nil, nil, io.EOF
		}
		m.read = true
		return m.single, nil, nil
	}
	if m.ended {
		return nil, nil, io.EOF
	}
	var blobs [][]byte
	var chunks []byte
	inBlob, total := false, 0
	for {
		if _, err := io.ReadFull(m.body, m.header[:]); err != nil {
			return nil, nil, truncated(err, "response ended without END frame")
		}
		kind, flags := m.header[0], m.header[1]
		length := binary.BigEndian.Uint32(m.header[4:])
		if length > maxFrame {
			return nil, nil, badGateway("Malformed Stream", fmt.Sprintf("frame of %d bytes exceeds the limit", length))
		}
		payload := make([]byte, length)
		if _, err := io.ReadFull(m.body, payload); err != nil {
			return nil, nil, truncated(err, "incomplete frame")
		}
		switch kind {
		case frameBlob:
			if total += len(payload); total > maxMessage {
				return nil, nil, badGateway("Malformed Stream", "blobs of one message exceed 64 MiB")
			}
			chunks = append(chunks, payload...)
			inBlob = true
			if flags&flagLast != 0 {
				if chunks == nil {
					chunks = []byte{}
				}
				blobs = append(blobs, chunks)
				chunks, inBlob = nil, false
			}
		case frameMsg:
			if inBlob {
				return nil, nil, badGateway("Malformed Stream", "MSG frame inside an unfinished blob")
			}
			return payload, blobs, nil
		case frameEnd:
			m.ended = true
			var info struct {
				Status  int            `json:"status"`
				Problem map[string]any `json:"problem"`
			}
			if err := json.Unmarshal(payload, &info); err != nil {
				return nil, nil, badGateway("Malformed Stream", "invalid END frame")
			}
			if info.Status >= 400 {
				return nil, nil, newError(info.Status, info.Problem)
			}
			return nil, nil, io.EOF
		}
		// HEARTBEAT, CHECKPOINT and unknown frame types are ignored.
	}
}

func truncated(err error, detail string) error {
	if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
		return badGateway("Truncated Stream", detail)
	}
	return err
}

// close releases the response; after END the (empty) rest is read so HTTP/1.1 can reuse the connection.
func (m *messages) close() {
	if m.ended {
		io.Copy(io.Discard, io.LimitReader(m.body, 64<<10))
	}
	m.body.Close()
}

// ---- unary calls -------------------------------------------------------------------------------

type noInput struct{}

func unary[O any](ctx context.Context, c *Client, name string, in any, opts []CallOption) (O, error) {
	var zero O
	op, config := lookup(name), callOptions(opts)
	var created []UploadRef
	defer func() { c.deleteUploads(ctx, created) }()
	method, path, h, body, err := c.prepare(ctx, name, op, in, config, &created)
	if err != nil {
		return zero, err
	}
	resp, err := c.send(ctx, method, path, h, body, true) // safe, or keyed
	if err != nil {
		return zero, err
	}
	msgs, err := newMessages(resp)
	if err != nil {
		return zero, err
	}
	defer msgs.close()
	payload, blobs, err := msgs.next()
	if err != nil {
		return zero, err
	}
	v, err := decodeValue[O](c, op, payload, blobs)
	if err != nil {
		return zero, err
	}
	if _, _, err := msgs.next(); err != io.EOF {
		if err == nil {
			err = badGateway("Malformed Stream", "more than one message in a unary response")
		}
		return zero, err
	}
	return v, nil
}

// prepare maps a call to HTTP (SPEC §5): GET ?i= for cacheable reads up to 2 KiB, else POST.
func (c *Client) prepare(ctx context.Context, name string, op *opMeta, in any, config callConfig, created *[]UploadRef) (string, string, http.Header, []byte, error) {
	h := c.headers(ctx, config)
	_, absent := in.(noInput)
	var data []byte
	if !absent {
		var err error
		if data, err = json.Marshal(in); err != nil {
			return "", "", nil, nil, err
		}
		if op.inUploads {
			if data, err = c.uploadInputs(ctx, op, in, data, created); err != nil {
				return "", "", nil, nil, err
			}
		}
	}
	if op.Effect == "safe" && (op.Stream == "none" || op.Stream == "server") {
		path := "/" + name
		if !absent {
			tree, err := decodeTree(data)
			if err != nil {
				return "", "", nil, nil, err
			}
			canonical, err := canonicalJSON(tree)
			if err != nil {
				return "", "", nil, nil, err
			}
			path += "?i=" + encodeURIComponent(canonical)
		}
		if len(path) <= maxGetURL {
			return http.MethodGet, path, h, nil, nil
		}
	}
	if !absent {
		h.Set("Content-Type", mediaJSON)
	}
	if op.Effect != "safe" && op.Stream == "none" {
		key := config.key
		if key == "" {
			key = uuid4()
		}
		value, err := sfString(key)
		if err != nil {
			return "", "", nil, nil, err
		}
		h.Set("Idempotency-Key", value)
	}
	return http.MethodPost, "/" + name, h, data, nil
}

// ---- server streams ----------------------------------------------------------------------------

// ServerStream is the output of a server-streaming call. Recv returns the next item, io.EOF after
// the last one, or the stream's error (an *Error from its END frame). Close cancels the call.
type ServerStream[T any] struct {
	c       *Client
	op      *opMeta
	ctx     context.Context
	msgs    *messages
	cancel  context.CancelFunc
	uploads []UploadRef // made for the call's input, deleted when it ends
	err     error
}

func serverStream[T any](ctx context.Context, c *Client, name string, in any, opts []CallOption) (*ServerStream[T], error) {
	op, config := lookup(name), callOptions(opts)
	ctx, cancel := context.WithCancel(ctx)
	var created []UploadRef
	fail := func(err error) (*ServerStream[T], error) {
		cancel()
		c.deleteUploads(ctx, created)
		return nil, err
	}
	method, path, h, body, err := c.prepare(ctx, name, op, in, config, &created)
	if err != nil {
		return fail(err)
	}
	resp, err := c.send(ctx, method, path, h, body, op.Effect != "unsafe")
	if err != nil {
		return fail(err)
	}
	msgs, err := newMessages(resp)
	if err != nil {
		return fail(err)
	}
	return &ServerStream[T]{c: c, op: op, ctx: ctx, msgs: msgs, cancel: cancel, uploads: created}, nil
}

func (s *ServerStream[T]) finish(err error) {
	s.err = err
	s.msgs.close()
	s.cancel()
	s.c.deleteUploads(s.ctx, s.uploads)
	s.uploads = nil
}

// Recv returns the next item; io.EOF after the last one.
func (s *ServerStream[T]) Recv() (T, error) {
	var zero T
	if s.err != nil {
		return zero, s.err
	}
	payload, blobs, err := s.msgs.next()
	if err == nil {
		var v T
		if v, err = decodeValue[T](s.c, s.op, payload, blobs); err == nil {
			return v, nil
		}
	}
	s.finish(err)
	return zero, err
}

// All iterates over the items; a failure is the last pair (with a zero item). Breaking out of the
// loop cancels the call.
func (s *ServerStream[T]) All() iter.Seq2[T, error] {
	return func(yield func(T, error) bool) {
		defer s.Close()
		for {
			v, err := s.Recv()
			if err == io.EOF {
				return
			}
			if !yield(v, err) || err != nil {
				return
			}
		}
	}
}

// Close cancels the call if it is still running.
func (s *ServerStream[T]) Close() error {
	if s.err == nil {
		s.finish(errors.New("apue: stream closed"))
	}
	return nil
}

// ---- request streams (client and bidi) ---------------------------------------------------------

// requestStream is a POST whose body is written while the response is read (full duplex over
// HTTP/2; net/http also reads an early response over HTTP/1.1).
type requestStream struct {
	c      *Client
	op     *opMeta
	ctx    context.Context
	cancel context.CancelFunc
	pw     *io.PipeWriter
	done   chan struct{} // closed once resp/err are set
	resp   *http.Response
	msgs   *messages
	err    error
	mu     sync.Mutex // serialises writes
	closed bool       // CloseSend called
	recvd  error      // sticky Recv result (io.EOF or the failure)
}

func (c *Client) openStream(ctx context.Context, name string, opts []CallOption) (*requestStream, error) {
	op, config := lookup(name), callOptions(opts)
	ctx, cancel := context.WithCancel(ctx)
	h := c.headers(ctx, config)
	h.Set("Content-Type", mediaStream)
	h.Set("Incremental", "?1") // RFC 10036: intermediaries must not buffer the request stream
	pr, pw := io.Pipe()
	req, err := c.newRequest(ctx, http.MethodPost, c.baseURL+"/"+name, h, pr)
	if err != nil {
		cancel()
		return nil, err
	}
	s := &requestStream{c: c, op: op, ctx: ctx, cancel: cancel, pw: pw, done: make(chan struct{})}
	context.AfterFunc(ctx, func() { pr.CloseWithError(context.Cause(ctx)) })
	go func() {
		defer close(s.done)
		s.resp, s.err = c.http.Do(req) // request streams are never retried: the body can't be replayed
		if s.err == nil {
			s.msgs, s.err = newMessages(s.resp)
		}
	}()
	return s, nil
}

func (s *requestStream) send(v any) error {
	frames, err := encodeMessage(s.op, v)
	if err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return errors.New("apue: Send after CloseSend")
	}
	if _, err := s.pw.Write(frames); err != nil {
		return s.sendFailed(err)
	}
	return nil
}

func (s *requestStream) closeSend() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil
	}
	s.closed = true
	_, err := s.pw.Write(appendFrame(nil, frameEnd, 0, []byte(`{"status":200}`)))
	s.pw.Close()
	if err != nil {
		return s.sendFailed(err)
	}
	return nil
}

// sendFailed: the request body was closed — the server answered early (maybe with an error) or the
// call was cancelled. Like gRPC, a stream the server ended reports io.EOF; Recv has the outcome.
func (s *requestStream) sendFailed(err error) error {
	select {
	case <-s.done:
		if s.err != nil {
			return s.err
		}
		return io.EOF
	case <-s.ctx.Done():
		return context.Cause(s.ctx)
	}
}

func (s *requestStream) next() ([]byte, [][]byte, error) {
	if s.recvd != nil {
		return nil, nil, s.recvd
	}
	select {
	case <-s.done:
	case <-s.ctx.Done():
		s.recvd = context.Cause(s.ctx)
		return nil, nil, s.recvd
	}
	if s.err != nil {
		s.recvd = s.err
		s.cancel()
		return nil, nil, s.err
	}
	payload, blobs, err := s.msgs.next()
	if err != nil {
		s.recvd = err
		s.msgs.close()
		s.cancel()
	}
	return payload, blobs, err
}

func (s *requestStream) close() {
	s.mu.Lock()
	s.closed = true
	s.mu.Unlock()
	s.cancel()
	go func() {
		<-s.done
		if s.msgs != nil {
			s.msgs.body.Close()
		}
	}()
}

func recvValue[T any](s *requestStream) (T, error) {
	var zero T
	payload, blobs, err := s.next()
	if err != nil {
		return zero, err
	}
	v, err := decodeValue[T](s.c, s.op, payload, blobs)
	if err != nil {
		s.recvd = err
		s.msgs.close()
		s.cancel()
	}
	return v, err
}

// ClientStream is a client-streaming call: Send the inputs, then CloseAndRecv for the output.
type ClientStream[I, O any] struct{ s *requestStream }

func openClientStream[I, O any](ctx context.Context, c *Client, name string, opts []CallOption) (*ClientStream[I, O], error) {
	s, err := c.openStream(ctx, name, opts)
	if err != nil {
		return nil, err
	}
	return &ClientStream[I, O]{s}, nil
}

// Send sends one input. io.EOF means the server has already answered: see CloseAndRecv.
func (cs *ClientStream[I, O]) Send(v I) error { return cs.s.send(v) }

// CloseAndRecv ends the inputs and returns the output.
func (cs *ClientStream[I, O]) CloseAndRecv() (O, error) {
	var zero O
	if err := cs.s.closeSend(); err != nil && err != io.EOF {
		return zero, err
	}
	v, err := recvValue[O](cs.s)
	if err != nil {
		return zero, err
	}
	if _, _, err := cs.s.next(); err != io.EOF {
		if err == nil {
			err = badGateway("Malformed Stream", "more than one output message")
		}
		return zero, err
	}
	return v, nil
}

// Close cancels the call if it is still running.
func (cs *ClientStream[I, O]) Close() error { cs.s.close(); return nil }

// BidiStream is a bidirectional call, full duplex over HTTP/2: Send and Recv may interleave (and run
// in different goroutines). Recv returns io.EOF after the last output.
type BidiStream[I, O any] struct{ s *requestStream }

func openBidiStream[I, O any](ctx context.Context, c *Client, name string, opts []CallOption) (*BidiStream[I, O], error) {
	s, err := c.openStream(ctx, name, opts)
	if err != nil {
		return nil, err
	}
	return &BidiStream[I, O]{s}, nil
}

// Send sends one input. io.EOF means the server has ended the call: Recv has the outcome.
func (b *BidiStream[I, O]) Send(v I) error { return b.s.send(v) }

// CloseSend ends the inputs.
func (b *BidiStream[I, O]) CloseSend() error { return b.s.closeSend() }

// Recv returns the next output; io.EOF after the last one.
func (b *BidiStream[I, O]) Recv() (O, error) { return recvValue[O](b.s) }

// All iterates over the outputs; a failure is the last pair.
func (b *BidiStream[I, O]) All() iter.Seq2[O, error] {
	return func(yield func(O, error) bool) {
		for {
			v, err := b.Recv()
			if err == io.EOF {
				return
			}
			if !yield(v, err) || err != nil {
				b.Close()
				return
			}
		}
	}
}

// Close cancels the call if it is still running.
func (b *BidiStream[I, O]) Close() error { b.s.close(); return nil }

// ---- uploads (bytes and file inputs of unary calls) --------------------------------------------

// UploadRef references content uploaded to /$uploads; it stands in for bytes in an input.
type UploadRef struct {
	ID string `json:"$upload"`
}

// File is the content of a t.file() input: uploaded before the call (streamed, never held in
// memory when it comes from a reader) and deleted after it.
type File struct{ src *fileSource }

type fileSource struct {
	key  string
	data []byte
	r    io.Reader
	used atomic.Bool
	ref  string
}

var fileKeys atomic.Uint64

func newFile(src *fileSource) File {
	src.key = strconv.FormatUint(fileKeys.Add(1), 10)
	return File{src}
}

// FileFromReader streams r to the server (once: a reader can't be read twice).
func FileFromReader(r io.Reader) File { return newFile(&fileSource{r: r}) }

// FileFromBytes uploads b.
func FileFromBytes(b []byte) File { return newFile(&fileSource{data: b}) }

// FileFromUpload uses content uploaded before (Client.Upload); it is not deleted after the call.
func FileFromUpload(ref UploadRef) File { return newFile(&fileSource{ref: ref.ID}) }

// MarshalJSON writes the upload reference, or a placeholder the client replaces while uploading.
func (f File) MarshalJSON() ([]byte, error) {
	switch {
	case f.src == nil:
		return nil, errors.New("apue: empty File (use FileFromReader, FileFromBytes or FileFromUpload)")
	case f.src.ref != "":
		return json.Marshal(UploadRef{f.src.ref})
	default:
		return json.Marshal(map[string]string{filePlaceholder: f.src.key})
	}
}

func (f File) reader() (io.Reader, error) {
	if f.src.data != nil {
		return bytes.NewReader(f.src.data), nil
	}
	if f.src.used.Swap(true) {
		return nil, errors.New("apue: a File from a reader can only be uploaded once")
	}
	return f.src.r, nil
}

// Upload uploads content in one request (POST /$uploads, Upload-Complete: ?1) and returns its
// reference. The caller owns it (DeleteUpload); uploads made for a call are deleted after it.
func (c *Client) Upload(ctx context.Context, r io.Reader) (UploadRef, error) {
	h := http.Header{}
	h.Set("Upload-Complete", "?1")
	h.Set("Content-Type", "application/octet-stream")
	req, err := c.newRequest(ctx, http.MethodPost, c.baseURL+uploadsPath, h, r)
	if err != nil {
		return UploadRef{}, err
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return UploadRef{}, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return UploadRef{}, err
	}
	if resp.StatusCode != http.StatusCreated {
		return UploadRef{}, problemFrom(resp.StatusCode, body)
	}
	var result struct {
		Upload string `json:"upload"`
	}
	if json.Unmarshal(body, &result) != nil || result.Upload == "" {
		return UploadRef{}, badGateway("Bad Gateway", "upload answered without a reference")
	}
	return UploadRef{result.Upload}, nil
}

// DeleteUpload deletes uploaded content.
func (c *Client) DeleteUpload(ctx context.Context, ref UploadRef) error {
	req, err := c.newRequest(ctx, http.MethodDelete, c.baseURL+uploadsPath+"/"+url.PathEscape(ref.ID), nil, nil)
	if err != nil {
		return err
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if resp.StatusCode >= 400 {
		return problemFrom(resp.StatusCode, body)
	}
	return nil
}

func (c *Client) deleteUploads(ctx context.Context, refs []UploadRef) {
	if len(refs) == 0 {
		return
	}
	ctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
	defer cancel()
	for _, ref := range refs {
		c.DeleteUpload(ctx, ref) // best effort: uploads expire anyway
	}
}

// uploadInputs uploads the bytes and files of a unary input and returns the input JSON with
// {"$upload": id} in their place (schema-directed, so nothing needs escaping).
func (c *Client) uploadInputs(ctx context.Context, op *opMeta, in any, data []byte, created *[]UploadRef) ([]byte, error) {
	tree, err := decodeTree(data)
	if err != nil {
		return nil, err
	}
	files := map[string]File{}
	collectFiles(reflect.ValueOf(in), files, 0)
	if tree, err = c.withUploads(ctx, op.Input, tree, files, created); err != nil {
		return nil, err
	}
	return json.Marshal(tree)
}

func (c *Client) withUploads(ctx context.Context, schema map[string]any, v any, files map[string]File, created *[]UploadRef) (any, error) {
	if branch, ok := nonNull(schema); ok {
		if v == nil {
			return nil, nil
		}
		return c.withUploads(ctx, branch, v, files, created)
	}
	var err error
	if kind := transfer(schema); kind == "blob-frames" || kind == "upload" {
		var r io.Reader
		if m, ok := v.(map[string]any); ok {
			if _, ok := m["$upload"]; ok && len(m) == 1 {
				return m, nil // FileFromUpload
			}
			key, _ := m[filePlaceholder].(string)
			f, ok := files[key]
			if !ok {
				return nil, errors.New("apue: unknown File in input")
			}
			if r, err = f.reader(); err != nil {
				return nil, err
			}
		} else {
			data, err := blobBytes(v)
			if err != nil {
				return nil, err
			}
			r = bytes.NewReader(data)
		}
		ref, err := c.Upload(ctx, r)
		if err != nil {
			return nil, err
		}
		*created = append(*created, ref)
		return map[string]any{"$upload": ref.ID}, nil
	}
	switch x := v.(type) {
	case []any:
		items := sub(schema, "items")
		for i := range x {
			if x[i], err = c.withUploads(ctx, items, x[i], files, created); err != nil {
				return nil, err
			}
		}
	case map[string]any:
		props := sub(schema, "properties")
		for k, e := range x {
			if p := sub(props, k); p != nil {
				if x[k], err = c.withUploads(ctx, p, e, files, created); err != nil {
					return nil, err
				}
			}
		}
	}
	return v, nil
}

var (
	fileType     = reflect.TypeFor[File]()
	downloadType = reflect.TypeFor[Download]()
)

// collectFiles finds the Files in an input (to upload their content).
func collectFiles(v reflect.Value, out map[string]File, depth int) {
	if !v.IsValid() || depth > 256 {
		return
	}
	switch v.Kind() {
	case reflect.Pointer, reflect.Interface:
		if !v.IsNil() {
			collectFiles(v.Elem(), out, depth+1)
		}
	case reflect.Struct:
		if v.Type() == fileType {
			if f := v.Interface().(File); f.src != nil {
				out[f.src.key] = f
			}
			return
		}
		for i := range v.NumField() {
			if v.Type().Field(i).IsExported() {
				collectFiles(v.Field(i), out, depth+1)
			}
		}
	case reflect.Slice, reflect.Array:
		if v.Type().Elem().Kind() == reflect.Uint8 {
			return
		}
		for i := range v.Len() {
			collectFiles(v.Index(i), out, depth+1)
		}
	case reflect.Map:
		for it := v.MapRange(); it.Next(); {
			collectFiles(it.Value(), out, depth+1)
		}
	}
}

// ---- downloads (t.download() outputs) ----------------------------------------------------------

// Download is a t.download() output: URL works as a plain link until Expires; Open reads the
// content, resuming a lost connection with Range + If-Range and verifying the SHA-256.
type Download struct {
	Path    string // path of the download resource on the API's origin
	URL     string // absolute URL
	Size    int64
	Type    string
	SHA256  string // hex; empty if the server doesn't know it
	Expires time.Time
	client  *Client
}

type downloadRef struct {
	Download string `json:"$download"`
	Size     int64  `json:"size"`
	Type     string `json:"type"`
	SHA256   string `json:"sha256,omitempty"`
	Expires  string `json:"expires"`
}

// UnmarshalJSON reads a download reference {"$download", "size", "type", "sha256"?, "expires"}.
func (d *Download) UnmarshalJSON(data []byte) error {
	if string(data) == "null" {
		return nil
	}
	var ref downloadRef
	if err := json.Unmarshal(data, &ref); err != nil {
		return err
	}
	if ref.Download == "" || ref.Size < 0 {
		return errors.New("apue: not a download reference")
	}
	expires, err := time.Parse(time.RFC3339Nano, ref.Expires)
	if err != nil {
		return fmt.Errorf("apue: download expiry: %w", err)
	}
	*d = Download{Path: ref.Download, URL: ref.Download, Size: ref.Size, Type: ref.Type, SHA256: ref.SHA256, Expires: expires}
	return nil
}

// MarshalJSON writes the download reference.
func (d Download) MarshalJSON() ([]byte, error) {
	return json.Marshal(downloadRef{d.Path, d.Size, d.Type, d.SHA256, d.Expires.UTC().Format(time.RFC3339Nano)})
}

// attach gives the Downloads in an output their client and absolute URL.
func (c *Client) attach(v reflect.Value, depth int) {
	if !v.IsValid() || depth > 256 {
		return
	}
	switch v.Kind() {
	case reflect.Pointer:
		if !v.IsNil() {
			c.attach(v.Elem(), depth+1)
		}
	case reflect.Struct:
		if v.Type() == downloadType {
			if v.CanAddr() {
				d := v.Addr().Interface().(*Download)
				d.client = c
				if u, err := c.base.Parse(d.Path); err == nil {
					d.URL = u.String()
				}
			}
			return
		}
		for i := range v.NumField() {
			if v.Type().Field(i).IsExported() {
				c.attach(v.Field(i), depth+1)
			}
		}
	case reflect.Slice, reflect.Array:
		for i := range v.Len() {
			c.attach(v.Index(i), depth+1)
		}
	}
}

// Open returns the content as a stream. A lost connection is resumed where it stopped (within the
// client's retry budget); a different representation behind the URL is an error, as is content
// that doesn't match the announced size or SHA-256 (reported by the last Read instead of io.EOF).
func (d *Download) Open(ctx context.Context) (io.ReadCloser, error) {
	if d.client == nil {
		return nil, errors.New("apue: this Download was not received by a Client")
	}
	return &downloadReader{d: d, ctx: ctx, hash: sha256.New()}, nil
}

// Bytes reads the whole content (verified like Open).
func (d *Download) Bytes(ctx context.Context) ([]byte, error) {
	r, err := d.Open(ctx)
	if err != nil {
		return nil, err
	}
	defer r.Close()
	return io.ReadAll(r)
}

type downloadReader struct {
	d        *Download
	ctx      context.Context
	body     io.ReadCloser
	received int64
	skip     int64
	etag     string
	failures int
	hash     interface {
		io.Writer
		Sum([]byte) []byte
	}
	err error
}

func (r *downloadReader) open() error {
	c := r.d.client
	h := http.Header{}
	if r.received > 0 {
		h.Set("Range", fmt.Sprintf("bytes=%d-", r.received))
		if r.etag != "" {
			h.Set("If-Range", r.etag)
		}
	}
	req, err := c.newRequest(r.ctx, http.MethodGet, r.d.URL, h, nil)
	if err != nil {
		return err
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return err
	}
	if resp.StatusCode >= 400 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		resp.Body.Close()
		return problemFrom(resp.StatusCode, body)
	}
	switch {
	case r.received == 0:
		if resp.StatusCode != http.StatusOK {
			resp.Body.Close()
			return badGateway("Bad Gateway", fmt.Sprintf("download answered %d", resp.StatusCode))
		}
		r.etag = resp.Header.Get("ETag")
	case resp.StatusCode == http.StatusPartialContent:
		if !strings.HasPrefix(resp.Header.Get("Content-Range"), fmt.Sprintf("bytes %d-", r.received)) {
			resp.Body.Close()
			return badGateway("Bad Gateway", "download resumed at the wrong offset")
		}
	case resp.StatusCode == http.StatusOK && r.etag != "" && resp.Header.Get("ETag") == r.etag:
		r.skip = r.received // the same content, sent whole: skip what we have
	default:
		resp.Body.Close()
		return badGateway("Bad Gateway", "the download changed while resuming")
	}
	r.body = resp.Body
	return nil
}

// retry decides whether a failure is resumed: not for problems or a cancelled context.
func (r *downloadReader) retry(err error) error {
	if r.body != nil {
		r.body.Close()
		r.body = nil
	}
	var problem *Error
	if errors.As(err, &problem) || r.ctx.Err() != nil {
		return err
	}
	if r.failures++; r.failures > r.d.client.retries {
		return err
	}
	return r.d.client.sleep(r.ctx, r.d.client.backoffFor(r.failures))
}

func (r *downloadReader) Read(p []byte) (int, error) {
	for r.err == nil {
		if r.body == nil {
			if err := r.open(); err != nil {
				r.err = r.retry(err)
				if r.err == nil {
					continue
				}
				break
			}
		}
		n, err := r.body.Read(p)
		if r.skip > 0 && n > 0 {
			cut := int(min(int64(n), r.skip))
			r.skip -= int64(cut)
			n = copy(p, p[cut:n])
		}
		if r.received+int64(n) > r.d.Size {
			r.err = badGateway("Bad Gateway", fmt.Sprintf("download larger than its announced %d bytes", r.d.Size))
			r.body.Close()
			break
		}
		r.received += int64(n)
		r.hash.Write(p[:n])
		if err == io.EOF {
			r.body.Close()
			r.body = nil
			if r.received == r.d.Size {
				r.err = io.EOF
				if r.d.SHA256 != "" && hex.EncodeToString(r.hash.Sum(nil)) != strings.ToLower(r.d.SHA256) {
					r.err = badGateway("Bad Gateway", "download content does not match its SHA-256")
				}
			} else {
				err = fmt.Errorf("apue: download ended after %d of %d bytes", r.received, r.d.Size) // truncated: resume
			}
		}
		if err != nil && err != io.EOF {
			r.err = r.retry(err)
		}
		if n > 0 {
			return n, nil
		}
	}
	return 0, r.err
}

func (r *downloadReader) Close() error {
	if r.body != nil {
		r.body.Close()
		r.body = nil
	}
	if r.err == nil {
		r.err = errors.New("apue: download closed")
	}
	return nil
}
